//! Route-level country rules and the unknown client identity, through the
//! public API, against the reference engine (`check_route_ip_access`,
//! `check_ip_access`). The verdict tables in `tests/data/route_country.json`
//! were generated by running the reference, never written by hand.

use bytes::Bytes;
use guard_core_engine::geo::{GeoIpHandler, parse_country_lists};
use http::{Request, Response, StatusCode};
use http_body_util::{BodyExt, Full};
use serde_json::Value;
use std::collections::BTreeMap;
use std::convert::Infallible;
use std::net::IpAddr;
use std::sync::Arc;
use tower::{Layer, ServiceExt};
use tower_guard_rs::{
    GeoStage, GeoStageConfig, GuardClientIp, GuardLayer, IpGateConfig, RouteConfig, default_config,
};

const TABLE: &str = include_str!("data/route_country.json");

struct Table {
    json: Value,
}

struct Countries(BTreeMap<String, String>);

impl GeoIpHandler for Countries {
    fn get_country(&self, ip: IpAddr) -> Option<String> {
        self.0.get(&ip.to_string()).cloned()
    }
}

impl Table {
    fn new() -> Self {
        Self {
            json: serde_json::from_str(TABLE).expect("fixture"),
        }
    }

    fn lists(&self, key: &str) -> Vec<Vec<String>> {
        self.json[key]
            .as_array()
            .expect(key)
            .iter()
            .map(|list| {
                list.as_array()
                    .expect("list")
                    .iter()
                    .map(|v| v.as_str().expect("entry").to_owned())
                    .collect()
            })
            .collect()
    }

    fn ips(&self) -> Vec<String> {
        self.json["ips"]
            .as_array()
            .expect("ips")
            .iter()
            .map(|v| v.as_str().expect("ip").to_owned())
            .collect()
    }

    fn handler(&self) -> Arc<dyn GeoIpHandler> {
        let map = self.json["countries"]
            .as_object()
            .expect("countries")
            .iter()
            .filter_map(|(ip, country)| Some((ip.clone(), country.as_str()?.to_owned())))
            .collect();
        Arc::new(Countries(map))
    }

    fn verdicts(&self, key: &str) -> Vec<char> {
        self.json[key].as_str().expect(key).chars().collect()
    }
}

async fn status_of(layer: &GuardLayer, ip: &str, route: Option<&RouteConfig>) -> StatusCode {
    let mut request = Request::builder().uri("/api");
    if ip != "unknown" {
        request = request.extension(GuardClientIp(ip.parse::<IpAddr>().expect("ip")));
    }
    let mut request = request.body(Full::new(Bytes::new())).expect("request");
    if let Some(route) = route {
        request.extensions_mut().insert(Arc::new(route.clone()));
    }
    let response = layer
        .layer(tower::service_fn(|_request: Request<Full<Bytes>>| async {
            Ok::<_, Infallible>(Response::new(Full::new(Bytes::from("ok"))))
        }))
        .oneshot(request)
        .await
        .expect("response");
    let status = response.status();
    let _ = response.into_body().collect().await;
    status
}

fn route_of(
    whitelist: &[String],
    blacklist: &[String],
    blocked: &[String],
    countries: &[String],
) -> RouteConfig {
    let some = |list: &[String]| (!list.is_empty()).then(|| list.to_vec());
    RouteConfig {
        ip_whitelist: some(whitelist),
        ip_blacklist: some(blacklist),
        blocked_countries: some(blocked),
        whitelist_countries: some(countries),
        ..RouteConfig::default()
    }
}

fn global_layer(table: &Table, whitelist: &[String], countries: &[String]) -> GuardLayer {
    let mut layer = GuardLayer::new(default_config());
    if !whitelist.is_empty() {
        layer = layer.with_ip_gate(
            IpGateConfig::new(whitelist, [] as [&str; 0], [] as [&str; 0]).expect("lists"),
        );
    }
    let handler = table.handler();
    if !countries.is_empty() {
        layer = layer.with_geo_blocking(
            GeoStage::builder(GeoStageConfig {
                gate: parse_country_lists(countries, [] as [&str; 0]),
                handler: Some(handler.clone()),
                passive_mode: false,
            })
            .build(),
        );
    }
    layer.with_geo_handler(handler)
}

fn allowed(verdict: char) -> bool {
    verdict != 'F'
}

#[tokio::test]
async fn route_verdicts_match_the_reference() {
    let table = Table::new();
    let (lists, blocked, countries) = (
        table.lists("route_lists"),
        table.lists("blocked_countries"),
        table.lists("whitelist_countries"),
    );
    let verdicts = table.verdicts("route");
    let layer = global_layer(&table, &[], &[]);
    let mut row = 0;
    let mut failures = Vec::new();
    for rwl in &lists {
        for rbl in &lists {
            for bc in &blocked {
                for wc in &countries {
                    for ip in table.ips() {
                        let route = route_of(rwl, rbl, bc, wc);
                        let got = status_of(&layer, &ip, Some(&route)).await;
                        let want = if allowed(verdicts[row]) {
                            StatusCode::OK
                        } else {
                            StatusCode::FORBIDDEN
                        };
                        if got != want {
                            failures.push(format!(
                                "rwl={rwl:?} rbl={rbl:?} bc={bc:?} wc={wc:?} ip={ip}: got {got} want {want}"
                            ));
                        }
                        row += 1;
                    }
                }
            }
        }
    }
    assert_eq!(row, verdicts.len());
    assert!(
        failures.is_empty(),
        "{} of {row} route rows differ:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[tokio::test]
async fn global_verdicts_match_the_reference() {
    let table = Table::new();
    let (lists, countries) = (
        table.lists("global_lists"),
        table.lists("global_whitelist_countries"),
    );
    let verdicts = table.verdicts("global");
    let mut row = 0;
    let mut failures = Vec::new();
    for wl in &lists {
        for wc in &countries {
            let layer = global_layer(&table, wl, wc);
            for ip in table.ips() {
                let got = status_of(&layer, &ip, None).await;
                let want = if allowed(verdicts[row]) {
                    StatusCode::OK
                } else {
                    StatusCode::FORBIDDEN
                };
                if got != want {
                    failures.push(format!(
                        "wl={wl:?} wc={wc:?} ip={ip}: got {got} want {want}"
                    ));
                }
                row += 1;
            }
        }
    }
    assert_eq!(row, verdicts.len());
    assert!(
        failures.is_empty(),
        "{} of {row} global rows differ:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[tokio::test]
async fn route_and_global_rules_compose_like_the_reference() {
    let table = Table::new();
    let (lists, blocked, countries, glists, gcountries) = (
        table.lists("route_lists"),
        table.lists("blocked_countries"),
        table.lists("whitelist_countries"),
        table.lists("global_lists"),
        table.lists("global_whitelist_countries"),
    );
    let verdicts = table.verdicts("combined");
    let mut row = 0;
    let mut failures = Vec::new();
    for rwl in &lists {
        for bc in &blocked {
            for wc in &countries {
                for gwl in &glists {
                    for gwc in &gcountries {
                        let layer = global_layer(&table, gwl, gwc);
                        let route = route_of(rwl, &[], bc, wc);
                        for ip in table.ips() {
                            let got = status_of(&layer, &ip, Some(&route)).await;
                            let want = if allowed(verdicts[row]) {
                                StatusCode::OK
                            } else {
                                StatusCode::FORBIDDEN
                            };
                            if got != want {
                                failures.push(format!(
                                    "route(wl={rwl:?} bc={bc:?} wc={wc:?}) global(wl={gwl:?} wc={gwc:?}) ip={ip}: got {got} want {want}"
                                ));
                            }
                            row += 1;
                        }
                    }
                }
            }
        }
    }
    assert_eq!(row, verdicts.len());
    assert!(
        failures.is_empty(),
        "{} of {row} combined rows differ:\n{}",
        failures.len(),
        failures.join("\n")
    );
}
